<script setup>
import {computed,ref,onUnmounted,watch} from 'vue';import {keyEvents,useInvestigation,time,sourceName} from './useInvestigation';import ChatContent from './ChatContent.vue';import EvidenceDetail from './EvidenceDetail.vue';
const {state,select}=useInvestigation();const index=ref(0),chat=ref(false),details=ref(false),playing=ref(false);const e=computed(()=>keyEvents[index.value]);let timer;
function step(n){index.value=Math.max(0,Math.min(4,index.value+n));select(e.value.id)}
function play(){if(playing.value){clearInterval(timer);playing.value=false;return}if(index.value===4)index.value=0;playing.value=true;timer=setInterval(()=>{if(index.value<4)step(1);else{clearInterval(timer);playing.value=false}},2600)}
watch(()=>state.selected?.id,id=>{const i=keyEvents.findIndex(event=>event.id===id);if(i>=0)index.value=i});
onUnmounted(()=>clearInterval(timer));
</script><template><div class="playback-layout"><header class="playback-header"><span class="wordmark">TRACE / REPLAY</span><span>תחקיר 041 <i></i> נתונים מדומים</span><button @click="chat=!chat">שאלו את TRACE ↖</button></header><main class="playback-stage"><aside class="playback-index"><span class="eyeline">פרקי האירוע</span><button v-for="(event,i) in keyEvents" :key="event.id" @click="index=i;select(event.id)" :class="{active:index===i}"><b>{{String(i+1).padStart(2,'0')}}</b><span>{{event.title}}</span></button></aside><section class="playback-scene"><div class="playback-scene-top"><span class="eyeline">{{sourceName(e)}}</span><span>רגע {{index+1}} מתוך 5</span></div><bdi class="cinema-time">{{time(e.t)}}</bdi><h1>{{e.title}}</h1><p>{{e.detail}}</p><div v-if="e.end" class="cinema-duration"><span class="duration-stroke"></span><span>{{e.end-e.t}} שניות</span><bdi>{{time(e.t)}} — {{time(e.end)}}</bdi></div><button class="cinema-evidence" @click="details=!details">{{details?'סגירת רשומה':'בחינת הראיה'}} <span>{{e.id}} ↗</span></button><EvidenceDetail v-if="details" :event="e" compact/></section><div class="scene-number" aria-hidden="true">0{{index+1}}</div></main><footer class="playback-controls"><div><span class="eyeline">חלון האירוע</span><bdi>14:32:00 — 14:34:27</bdi></div><div class="replay-track" dir="ltr"><button v-for="(event,i) in keyEvents" :key="event.id" :class="{active:index===i}" :style="{left:((event.t-120)/147*100)+'%'}" @click="index=i;select(event.id)" :aria-label="event.title"></button></div><div class="replay-buttons" dir="ltr"><button @click="step(-1)" :disabled="index===0" aria-label="Previous moment">←</button><button class="play-button" @click="play">{{playing?'Pause':'Play'}}</button><button @click="step(1)" :disabled="index===4" aria-label="Next moment">→</button></div></footer><aside v-if="chat" class="playback-chat popover-chat"><button class="close-button" @click="chat=false" aria-label="סגירת שיחה">×</button><ChatContent/></aside></div></template>